**Idea** – Instead of judging an action only by a one‑round “deficit” estimate, this policy performs a short exhaustive look‑ahead (up to 4 future rounds).  It searches the game tree for an action that *guarantees* a win within the horizon, using the exact damage/advance mechanics, and falls back to a simple deterministic heuristic only when no forced win is found.  This deeper reasoning lets the agent plan merges or relocations that only pay off a couple of rounds later, something the previous champion could not anticipate.

```python
NUM_COLUMNS = 5
MAX_POSITION = 3  # reaching this loses the game
MAX_DEPTH = 4     # look‑ahead horizon


class Policy:
    name = "depth_search_with_fallback"

    # ------------------------------------------------------------------ #
    def choose_action(self, engine):
        # --------------------------------------------------------------
        # Helper: deep copy of state structures
        def copy_cannons(c):
            return dict(c)

        def copy_pirates(p):
            return [dict(p_) for p_ in p]

        # --------------------------------------------------------------
        # Simulate one full round (damage then advance) after applying an action
        def simulate_round(cannons_map, pirates_list):
            cannons = copy_cannons(cannons_map)
            pirates = copy_pirates(pirates_list)

            # damage phase – each column hits its front pirate
            for col, dmg in cannons.items():
                if dmg <= 0:
                    continue
                col_p = [p for p in pirates if p["column"] == col]
                if not col_p:
                    continue
                front = max(col_p, key=lambda p: p["position"])
                front["hp"] -= dmg
                if front["hp"] <= 0:
                    pirates.remove(front)

            # advance phase
            for p in pirates:
                p["position"] += 1

            # loss check
            loss = any(p["position"] >= MAX_POSITION for p in pirates)
            return cannons, pirates, loss

        # --------------------------------------------------------------
        # Generate every legal action for the current cannon layout
        def actions_for(cannons):
            acts = []
            # spawn actions (including merges)
            for col in range(NUM_COLUMNS):
                acts.append(("spawn", col))
            # move actions
            for donor in cannons:
                for target in range(NUM_COLUMNS):
                    if donor == target:
                        continue
                    acts.append(("move", donor, target))
            return acts

        # --------------------------------------------------------------
        # Depth‑first search for a guaranteed win within the horizon
        def search(cannons, pirates, depth):
            if not pirates:
                # already cleared – no further action needed (should not happen here)
                return True, None
            if depth == 0:
                return False, None

            for act in actions_for(cannons):
                # ----- apply action -----
                new_cannons = copy_cannons(cannons)
                if act[0] == "spawn":
                    col = act[1]
                    new_cannons[col] = new_cannons.get(col, 0) + 1
                else:  # move
                    donor, target = act[1], act[2]
                    dmg = new_cannons.pop(donor)
                    new_cannons[target] = new_cannons.get(target, 0) + dmg
                    # the pending spawn cannon is lost – nothing else to do

                # ----- simulate round -----
                post_cannons, post_pirates, loss = simulate_round(new_cannons, pirates)
                if loss:
                    continue          # discard losing branches
                if not post_pirates:
                    # immediate win after this action
                    return True, act

                # ----- recurse -----
                win, _ = search(post_cannons, post_pirates, depth - 1)
                if win:
                    return True, act

            return False, None

        # --------------------------------------------------------------
        # Gather current state in simple dict/list form
        cur_cannons = {c: engine.cannons[c].damage for c in engine.cannons}
        cur_pirates = [
            {"column": p.column, "position": p.position, "hp": p.hp}
            for p in engine.pirates
        ]

        # --------------------------------------------------------------
        # Try to find a forced win within the look‑ahead horizon
        win_possible, winning_action = search(cur_cannons, cur_pirates, MAX_DEPTH)
        if win_possible and winning_action is not None:
            return winning_action

        # --------------------------------------------------------------
        # Fallback heuristic (deterministic, no randomness)
        # 1) compute total HP per column
        hp_per_col = [0] * NUM_COLUMNS
        for p in cur_pirates:
            hp_per_col[p["column"]] += p["hp"]

        # 2) Prefer spawning (or merging) on the column with the most remaining HP
        best_col = max(range(NUM_COLUMNS), key=lambda c: (hp_per_col[c], c))
        if best_col not in engine.cannons:
            return ("spawn", best_col)

        # 3) If every column already has a cannon, move the weakest cannon
        #    to the column with the highest HP total (if different)
        weakest_col = min(cur_cannons, key=lambda c: (cur_cannons[c], c))
        if weakest_col != best_col:
            return ("move", weakest_col, best_col)

        # 4) As a final deterministic fallback, just spawn on column 0
        return ("spawn", 0)
